Q: MERN Stack Email Confirmation A: <p>nodemailer should be implemented on the backend, not in react frontend.</p>
<p>backend generates a jwt token, creates a verification link, and sends it using nodemailer. react only handles the verification page and sends the token back to the backend.</p>
<p>backend verifies the token and updates the user's verification status in mongodb.</p>
<pre><code>// backend express

const jwt = require(&quot;jsonwebtoken&quot;);
const nodemailer = require(&quot;nodemailer&quot;);

app.post(&quot;/login&quot;, async (req, res) =&gt; {
  const { email } = req.body;

  const token = jwt.sign(
    { email },
    process.env.JWT_SECRET,
    { expiresIn: &quot;1h&quot; }
  );

  const verifyLink = `http://localhost:3000/verify/${token}`;

  const transporter = nodemailer.createTransport({
    service: &quot;gmail&quot;,
    auth: {
      user: process.env.EMAIL,
      pass: process.env.PASSWORD,
    },
  });

  await transporter.sendMail({
    from: process.env.EMAIL,
    to: email,
    subject: &quot;verify email&quot;,
    html: `&lt;a href=&quot;${verifyLink}&quot;&gt;verify email&lt;/a&gt;`,
  });

  res.json({
    message: &quot;verification email sent&quot;
  });
});


// verify token

app.post(&quot;/verify&quot;, async (req, res) =&gt; {
  const { token } = req.body;

  try {
    const decoded = jwt.verify(
      token,
      process.env.JWT_SECRET
    );

    await User.findOneAndUpdate(
      { email: decoded.email },
      { isVerified: true }
    );

    res.json({
      message: &quot;email verified&quot;
    });

  } catch (err) {
    res.status(400).json({
      message: &quot;invalid token&quot;
    });
  }
});
</code></pre>

Q: how main program.cs look like in web api A: <p><strong>// in Domain Domain Layer Keep Global ExceptionHandler</strong></p>
<pre><code>public class GlobalExceptionHandler : IExceptionHandler
{
    private readonly ILogger&lt;GlobalExceptionHandler&gt; _logger;

    public GlobalExceptionHandler(ILogger&lt;GlobalExceptionHandler&gt; logger)
    {
        _logger = logger;
    }

    public async ValueTask&lt;bool&gt; TryHandleAsync(HttpContext httpContext,Exception exception,CancellationToken cancellationToken)
    {
        _logger.LogError(exception, &quot;An unhandled exception occurred: {Message}&quot;, exception.Message);

        var (statusCode, title) = exception switch
        {

            customeException appEx =&gt; ((int)appEx.StatusCode, appEx.Message),
            ArgumentNullException =&gt; (StatusCodes.Status400BadRequest, &quot;Invalid argument provided&quot;),
            ArgumentException =&gt; (StatusCodes.Status400BadRequest, &quot;Invalid argument provided&quot;),
            UnauthorizedAccessException =&gt; (StatusCodes.Status401Unauthorized, &quot;Unauthorized&quot;),
            _ =&gt; (StatusCodes.Status500InternalServerError, &quot;An unexpected error occurred&quot;)
        };



        var problemDetails = new ProblemDetails
        {
            Status = statusCode,
            Title = title,
            Detail = exception.Message,
            Instance = httpContext.Request.Path
        };

        await httpContext.Response.WriteAsJsonAsync(problemDetails, cancellationToken);

        return true;
    }
}

// Now for Custome Exception Create a CustomeExceptionFolder and Add Two file 1 is customeExceptions.cs and 2nd is ExceptionTypes.cs 

// customeException.cs
  public abstract class customeException:Exception
   {
       public HttpStatusCode StatusCode { get; set; }

       protected customeException(string message, HttpStatusCode statusCode = HttpStatusCode.InternalServerError): base(message)
       {
           StatusCode = statusCode;
       }
   }

//ExceptionType.cs

    public sealed class NotFoundException : customeException
    {
        public NotFoundException(string resourceName)
            : base($&quot;{resourceName} with identifier  was not found.&quot;, HttpStatusCode.NotFound)
        {
        }
    }

    public sealed class BadRequestException : customeException
    {
        public BadRequestException(string message)
            : base(message, HttpStatusCode.BadRequest)
        {
        }
    }

    public sealed class ConflictException : customeException
    {
        public ConflictException(string message)
            : base(message, HttpStatusCode.Conflict)
        {
        }
    }


    public sealed class ValidationException : customeException
    {
        public IDictionary&lt;string, string[]&gt; Errors { get; }

        public ValidationException(IDictionary&lt;string, string[]&gt; errors)
            : base(&quot;One or more validation errors occurred.&quot;, HttpStatusCode.BadRequest)
        {
            Errors = errors;
        }

        public ValidationException(string field, string error)
            : base(&quot;One or more validation errors occurred.&quot;, HttpStatusCode.BadRequest)
        {
            Errors = new Dictionary&lt;string, string[]&gt;
        {
            { field, [error] }
        };
        }
    }
</code></pre>

